// Generated by GitHub Copilot
/**
 * dca.js — Module DCA (rétroviseur + projection)
 */

const DCAModule = (() => {
    let state = {
        data: [],
        startDate: null,
        endDate: null,
        monthlyAmount: 300,
        projectionYears: 10,
        projectionMonthly: 300,
        projectionRate: 0,
        periodRate: 0,
        userOverrideRate: false
    };

    const DOM = {
        monthlyAmountInput: null,
        projectionYearsInput: null,
        projectionMonthlyInput: null,
        projectionRateInput: null,
        projectionRateHint: null,
        projectionResetRateBtn: null,
        debugOutput: null,
        retroInvested: null,
        retroGain: null,
        retroBuyAndHold: null,
        projectionInvested: null,
        projectionGain: null,
        projectionFinal: null,
        tableBody: null
    };

    /**
     * @param {number} value
     * @returns {string}
     */
    const formatCurrency = (value) => {
        return new Intl.NumberFormat('fr-FR', {
            style: 'currency',
            currency: 'EUR',
            maximumFractionDigits: 2
        }).format(Number.isFinite(value) ? value : 0);
    };

    /**
     * @param {number} value
     * @returns {string}
     */
    const formatPercent = (value) => {
        const safe = Number.isFinite(value) ? value : 0;
        return `${safe >= 0 ? '+' : ''}${safe.toFixed(2)}%`;
    };

    /**
    * Agrège la série en points mensuels (premier close du mois).
     * @param {Array} data
     * @returns {Array}
     */
    const getMonthlySeries = (data) => {
        const monthlyMap = new Map();
        const sorted = [...data].sort((a, b) => a.date.localeCompare(b.date));

        for (const row of sorted) {
            const dateObj = new Date(`${row.date}T00:00:00`);
            if (Number.isNaN(dateObj.getTime())) {
                continue;
            }

            const key = `${dateObj.getFullYear()}-${String(dateObj.getMonth() + 1).padStart(2, '0')}`;
            if (!monthlyMap.has(key)) {
                monthlyMap.set(key, row);
            }
        }

        return Array.from(monthlyMap.entries()).map(([key, row]) => {
            const [year, month] = key.split('-').map(Number);
            return {
                key,
                year,
                month,
                date: row.date,
                close: Number(row.close)
            };
        });
    };

    /**
     * Calcule la section rétroviseur sur la période filtrée.
     * @param {Array} monthlySeries
     * @param {number} monthlyAmount
     * @returns {Object}
     */
    const calculateRetro = (monthlySeries, monthlyAmount) => {
        if (!monthlySeries.length || monthlyAmount <= 0) {
            return {
                totalInvested: 0,
                totalParts: 0,
                portfolioValue: 0,
                totalGainEur: 0,
                totalGainPct: 0,
                yearlyRows: []
            };
        }

        let totalParts = 0;
        let totalInvested = 0;
        const monthsByYear = new Map();
        const pointsByYear = new Map();

        for (const point of monthlySeries) {
            const boughtParts = monthlyAmount / point.close;
            totalParts += boughtParts;
            totalInvested += monthlyAmount;
            monthsByYear.set(point.year, (monthsByYear.get(point.year) || 0) + 1);
            
            // Stocker le dernier point de chaque année pour récupérer le prix
            if (!pointsByYear.has(point.year) || point.date > pointsByYear.get(point.year).date) {
                pointsByYear.set(point.year, point);
            }
        }

        const finalClose = monthlySeries[monthlySeries.length - 1].close;
        const portfolioValue = totalParts * finalClose;
        const totalGainEur = portfolioValue - totalInvested;
        const totalGainPct = totalInvested > 0 ? (totalGainEur / totalInvested) * 100 : 0;

        // Calcul des lignes annuelles basé sur les prix réels (cohérent avec le total)
        const yearlyRows = [];
        let cumulativePartsByYear = 0;
        let cumulativeInvestedByYear = 0;
        let previousGain = 0;

        const sortedYears = Array.from(monthsByYear.keys()).sort((a, b) => a - b);
        
        for (const year of sortedYears) {
            const monthCount = monthsByYear.get(year);
            const invested = monthlyAmount * monthCount;
            cumulativeInvestedByYear += invested;

            // Accumuler les parts jusqu'à fin d'année
            for (const point of monthlySeries) {
                if (point.year === year) {
                    cumulativePartsByYear += monthlyAmount / point.close;
                }
            }

            // Prix réel à la fin de cette année
            const lastPointThisYear = pointsByYear.get(year);
            const priceEndYear = lastPointThisYear ? lastPointThisYear.close : finalClose;

            // Valeur cumulative du portefeuille à la fin de cette année
            const portfolioValueCumul = cumulativePartsByYear * priceEndYear;

            // Gain cumulatif à fin d'année
            const gainCumulEur = portfolioValueCumul - cumulativeInvestedByYear;
            const gainCumulPct = cumulativeInvestedByYear > 0 
                ? (gainCumulEur / cumulativeInvestedByYear) * 100 
                : 0;

            // Gain GÉNÉRÉ cette année (gain cumul - gain année précédente)
            const gainGeneratedYear = gainCumulEur - previousGain;
            const gainGeneratedPct = cumulativeInvestedByYear > 0 
                ? (gainGeneratedYear / monthlyAmount) * 100 
                : 0;

            yearlyRows.push({
                year,
                invested,
                portfolioValue: portfolioValueCumul,
                gainEur: gainGeneratedYear,
                gainPct: gainGeneratedPct
            });

            previousGain = gainCumulEur;
        }

        return {
            totalInvested,
            totalParts,
            portfolioValue,
            totalGainEur,
            totalGainPct,
            yearlyRows
        };
    };

    /**
     * Calcule la projection future avec intérêts composés mensuels.
     * @param {number} years
     * @param {number} monthly
     * @param {number} annualReturnPct
     * @returns {Object}
     */
    const calculateProjection = (years, monthly, annualReturnPct) => {
        const n = Math.max(0, Math.round(years * 12));
        const safeMonthly = Math.max(0, monthly);
        const annualRate = Number.isFinite(annualReturnPct) ? annualReturnPct / 100 : 0;
        const monthlyRate = annualRate / 12;
        const totalInvested = safeMonthly * n;

        let portfolioFinal = 0;

        for (let m = 1; m <= n; m += 1) {
            const exponent = n - m + 1;
            portfolioFinal += safeMonthly * Math.pow(1 + monthlyRate, exponent);
        }

        const gain = portfolioFinal - totalInvested;
        const gainPct = totalInvested > 0 ? (gain / totalInvested) * 100 : 0;

        return {
            totalInvested,
            gain,
            gainPct,
            portfolioFinal
        };
    };

    /**
     * Rend le tableau récapitulatif annuel.
     * @param {Array} yearlyRows
     */
    const renderTable = (yearlyRows) => {
        if (!DOM.tableBody) {
            return;
        }

        if (!yearlyRows.length) {
            DOM.tableBody.innerHTML = '<tr><td colspan="5">Aucune donnée sur la période.</td></tr>';
            return;
        }

        const rowsHtml = yearlyRows.map((row) => {
            return `
                <tr>
                    <td>${row.year}</td>
                    <td>${formatCurrency(row.invested)}</td>
                    <td>${formatCurrency(row.portfolioValue)}</td>
                    <td>${formatCurrency(row.gainEur)}</td>
                    <td>${formatPercent(row.gainPct)}</td>
                </tr>
            `;
        }).join('');

        DOM.tableBody.innerHTML = rowsHtml;
    };

    /**
     * Rend le bloc debug avec l'état de calcul courant.
     * @param {Object} retro
     * @param {Object} projection
     * @param {number} monthlyPoints
     */
    const renderDebug = (retro, projection, monthlyPoints) => {
        if (!DOM.debugOutput) {
            return;
        }

        const debugPayload = {
            period: {
                startDate: state.startDate,
                endDate: state.endDate,
                monthlyPoints
            },
            rates: {
                currentPeriodReturn: Number(window.currentPeriodReturn) || 0,
                currentPeriodReturnPerYear: window.currentPeriodReturnPerYear || {},
                periodRateApplied: state.periodRate,
                projectionRateApplied: state.projectionRate,
                userOverrideRate: state.userOverrideRate
            },
            inputs: {
                monthlyAmount: state.monthlyAmount,
                projectionYears: state.projectionYears,
                projectionMonthly: state.projectionMonthly
            },
            retro: {
                totalInvested: retro.totalInvested,
                totalParts: retro.totalParts,
                portfolioValue: retro.portfolioValue,
                totalGainEur: retro.totalGainEur,
                totalGainPct: retro.totalGainPct,
                yearlyRows: retro.yearlyRows
            },
            projection: {
                totalInvested: projection.totalInvested,
                gainEur: projection.gain,
                gainPct: projection.gainPct,
                portfolioFinal: projection.portfolioFinal
            }
        };

        DOM.debugOutput.textContent = JSON.stringify(debugPayload, null, 2);
    };

    /**
     * Exécute les calculs et met à jour l'UI.
     * @param {Object} payload
     * @param {Array} payload.data
     * @param {string} payload.startDate
     * @param {string} payload.endDate
     */
    const calculate = (payload = {}) => {
        if (Array.isArray(payload.data)) {
            state.data = payload.data;
        }
        if (payload.startDate) {
            state.startDate = payload.startDate;
        }
        if (payload.endDate) {
            state.endDate = payload.endDate;
        }

        if (DOM.monthlyAmountInput) {
            state.monthlyAmount = Number(DOM.monthlyAmountInput.value) || 0;
        }
        if (DOM.projectionYearsInput) {
            state.projectionYears = Number(DOM.projectionYearsInput.value) || 0;
        }
        if (DOM.projectionMonthlyInput) {
            state.projectionMonthly = Number(DOM.projectionMonthlyInput.value) || 0;
        }

        state.periodRate = Number(window.currentPeriodReturn) || 0;
        if (!state.userOverrideRate && DOM.projectionRateInput) {
            state.projectionRate = state.periodRate;
            DOM.projectionRateInput.value = state.periodRate.toFixed(2);
        } else if (DOM.projectionRateInput) {
            state.projectionRate = Number(DOM.projectionRateInput.value) || 0;
        }

        if (DOM.projectionRateHint) {
            DOM.projectionRateHint.textContent = `Taux basé sur la période sélectionnée: ${state.periodRate.toFixed(2)}%`;
        }

        const monthlySeries = getMonthlySeries(state.data || []);
        const retro = calculateRetro(monthlySeries, state.monthlyAmount);
        const projection = calculateProjection(
            state.projectionYears,
            state.projectionMonthly,
            state.projectionRate
        );

        if (DOM.retroInvested) {
            DOM.retroInvested.textContent = formatCurrency(retro.totalInvested);
        }
        if (DOM.retroGain) {
            DOM.retroGain.textContent = `${formatCurrency(retro.totalGainEur)} (${formatPercent(retro.totalGainPct)})`;
            DOM.retroGain.className = `kpi-value ${retro.totalGainEur >= 0 ? 'positive' : 'negative'}`;
        }

        if (DOM.retroBuyAndHold) {
            const bahPct = Number(window.currentPeriodReturn) || 0;
            const bahGainEur = retro.totalInvested * (bahPct / 100);
            DOM.retroBuyAndHold.textContent = `${formatCurrency(bahGainEur)} (${formatPercent(bahPct)})`;
            DOM.retroBuyAndHold.className = `kpi-value ${bahPct >= 0 ? 'positive' : 'negative'}`;
        }

        if (DOM.projectionInvested) {
            DOM.projectionInvested.textContent = formatCurrency(projection.totalInvested);
        }
        if (DOM.projectionGain) {
            DOM.projectionGain.textContent = `${formatCurrency(projection.gain)} (${formatPercent(projection.gainPct)})`;
            DOM.projectionGain.className = `kpi-value ${projection.gain >= 0 ? 'positive' : 'negative'}`;
        }
        if (DOM.projectionFinal) {
            DOM.projectionFinal.textContent = formatCurrency(projection.portfolioFinal);
        }

        renderTable(retro.yearlyRows);
        renderDebug(retro, projection, monthlySeries.length);
    };

    /**
     * Initialise le module DCA et ses événements.
     */
    const init = () => {
        DOM.monthlyAmountInput = document.getElementById('dca-monthly-amount');
        DOM.projectionYearsInput = document.getElementById('dca-projection-years');
        DOM.projectionMonthlyInput = document.getElementById('dca-projection-monthly');
        DOM.projectionRateInput = document.getElementById('dca-projection-rate');
        DOM.projectionRateHint = document.getElementById('dca-projection-rate-hint');
        DOM.projectionResetRateBtn = document.getElementById('dca-reset-rate');
        DOM.debugOutput = document.getElementById('dca-debug-output');
        DOM.retroInvested = document.getElementById('dca-retro-invested');
        DOM.retroGain = document.getElementById('dca-retro-gain');
        DOM.retroBuyAndHold = document.getElementById('dca-retro-bah');
        DOM.projectionInvested = document.getElementById('dca-projection-invested');
        DOM.projectionGain = document.getElementById('dca-projection-gain');
        DOM.projectionFinal = document.getElementById('dca-projection-final');
        DOM.tableBody = document.getElementById('dca-yearly-body');

        if (!DOM.monthlyAmountInput || !DOM.projectionYearsInput || !DOM.projectionMonthlyInput || !DOM.projectionRateInput) {
            return false;
        }

        DOM.projectionRateInput.value = (Number(window.currentPeriodReturn) || 0).toFixed(2);

        DOM.monthlyAmountInput.addEventListener('input', () => {
            if (DOM.projectionMonthlyInput && !DOM.projectionMonthlyInput.dataset.userEdited) {
                DOM.projectionMonthlyInput.value = DOM.monthlyAmountInput.value;
            }
            calculate();
        });

        DOM.projectionYearsInput.addEventListener('input', () => calculate());

        DOM.projectionMonthlyInput.addEventListener('input', () => {
            DOM.projectionMonthlyInput.dataset.userEdited = 'true';
            calculate();
        });

        DOM.projectionRateInput.addEventListener('input', () => {
            state.userOverrideRate = true;
            calculate();
        });

        if (DOM.projectionResetRateBtn) {
            DOM.projectionResetRateBtn.addEventListener('click', () => {
                state.userOverrideRate = false;
                DOM.projectionRateInput.value = (Number(window.currentPeriodReturn) || 0).toFixed(2);
                calculate();
            });
        }

        return true;
    };

    return {
        init,
        calculate,
        renderTable
    };
})();

// Compatibilité avec l'ancien nom du module.
const DCASimulator = DCAModule;
